                steps: [
                    { formula: "පුරිස + නාහි", rule: "යෙන වා කයිරතෙ තං කරණං. & කරණෙ තතියා." },
                    { formula: "පුරිස + හි", rule: "බහුම්හි වත්තබ්බෙ බහුවචනං." },
                    { formula: "පුරිස් - අ→එ + හි", rule: "පුබ්බමධොඨිතමස්සරං සරෙන වියොජයෙ. & සුහිස්වකාරො එ." },
                    { formula: "පුරිස් - එ + හි → පුරිසෙහි", rule: "නයෙ පරං යුත්තෙ." }
                ],
                final_result: "පුරිසෙහි"
