                    { formula: "බ්‍රහ්ම් - අ→උ + නා", rule: "උත්තං සනාසු." },
                    { formula: "බ්‍රහ්ම් - උ + නා → බ්‍රහ්මුනා", rule: "නයෙ පරං යුත්තෙ." }
