            pada: "සස්ස, නො යනුවෙන් පද දෙකකි.",
            padattha_pali: "අත්තසද්දතො සස්ස විභත්තිස්ස නො හොතීති අත්ථො.",
            padattha: "අත්ත ශබ්දයා කෙරෙන් පර වූ ස විභක්තියට නො ආදේශය වේ යනු අර්ථයි.",
            padaviggaha_pali: "අතති සතතං ගච්ඡතීති අත්තා.",
